// Input constraint: path must be a valid, initialized fs::path object (provided by fuzzer runtime)
// We call the API directly with a const reference to the provided path
const fs::path &in = *path;
bool is_mfs = mergerfs::api::is_mergerfs(in);
// Record the probe result as metadata for potential downstream stubs
FUZZ_SET_ATTR_INT(path, "probe_count", FUZZ_GET_ATTR_INT(path, "probe_count") + 1);
FUZZ_SET_ATTR_INT(path, "last_is_mergerfs", is_mfs ? 1 : 0);
// Validation: API returns a boolean probe; no invariant to assert beyond non-crash behavior.
// We do not treat false as an error; no FUZZ_BAIL() here.

// Requirements:
// - mountpoint must be a valid fs::path (provided by runtime)
// - kvs must be a non-null pointer to a valid std::map<std::string,std::string>
const fs::path &mp = *mountpoint;
std::map<std::string, std::string> kvs;
int rc = mergerfs::api::get_kvs(mp, &kvs);
// Caller must check status before using kvs; we will only lightly touch kvs on apparent success
if (rc == 0) {
    // Access up to a few entries to exercise map iteration without heavy work
    size_t seen = 0;
    for (const auto &kv : kvs) {
        volatile size_t ksz = kv.first.size();
        volatile size_t vsz = kv.second.size();
        (void)ksz; (void)vsz;
        if (++seen >= 4) break;
    }
}
// Record result as metadata for potential later decisions
FUZZ_SET_ATTR_INT(mountpoint, "get_kvs_last_rc", rc);
// Validation: kvs is always a valid object we created; rc can be any int per API, so no assert.
// No persistent objects are produced, so no outputs are returned.

// Requirements:
// - path: valid string; we'll generate either a random filename (existing file) or arbitrary string
// - basepath: valid std::string lvalue reference to receive output
unsigned int pick = *FUZZ_PARAM(unsigned int);
std::string in;
if ((pick & 1u) == 0u) {
    // Use a fuzz-provided existing filename for path-like semantics
    const char *fname = FUZZ_PARAM_FILENAME();
    in.assign(fname);
} else {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 1024) s.resize(1024);
    in.swap(s);
}
std::string out_base;
int rc = mergerfs::api::basepath(in, out_base);
if (rc == 0) {
    // Light-touch use of output to cover write path
    volatile size_t len = out_base.size();
    (void)len;
}
// Validation: We respect the contract by checking rc before touching out_base; no persistent outputs.

