// Requirements:
// - path: valid string
// - paths: valid std::vector<std::string> lvalue reference to receive paths
unsigned int pick = *FUZZ_PARAM(unsigned int);
std::string in;
if ((pick & 1u) == 0u) {
    const char *fname = FUZZ_PARAM_FILENAME();
    in.assign(fname);
} else {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 1024) s.resize(1024);
    in.swap(s);
}
std::vector<std::string> out_paths;
int rc = mergerfs::api::allpaths(in, out_paths);
if (rc == 0) {
    // Touch a limited number of entries to exercise vector access
    size_t limit = out_paths.size();
    if (limit > 4) limit = 4;
    for (size_t i = 0; i < limit; ++i) {
        volatile size_t len = out_paths[i].size();
        (void)len;
    }
}
// Validation: We honor the status code before using outputs; no persistent objects returned.

// Construct a valid fs::path instance using fuzz-provided data without touching the filesystem.
// We exercise construction and concatenation paths to diversify coverage.

unsigned int mode = *FUZZ_PARAM(unsigned int);
std::string base;
if ((mode & 1u) == 0u) {
    // Use a fuzz-generated filename to get path-like formatting.
    const char *fname = FUZZ_PARAM_FILENAME();
    base.assign(fname);
} else {
    // Use arbitrary bytes (may include non-UTF8); clamp size for performance.
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 1024) s.resize(1024);
    base.swap(s);
}

// Optionally add extra components to explore operator/= behavior.
std::string compA, compB;
if ((mode & 2u) != 0u) {
    compA = FUZZ_PARAM_STR();
    if (compA.size() > 128) compA.resize(128);
}
if ((mode & 4u) != 0u) {
    compB = FUZZ_PARAM_STR();
    if (compB.size() > 128) compB.resize(128);
}

fs::path tmp(base);
if (!compA.empty()) tmp /= compA; // concatenation only; no I/O
if (!compB.empty()) tmp /= compB;

// Define and initialize the required output. The fuzzer runtime takes ownership.
fs::path *path = new fs::path(tmp);

// Attach attributes for downstream stubs to use.
FUZZ_SET_ATTR_INT(path, "probe_count", 0);
FUZZ_SET_ATTR_INT(path, "last_is_mergerfs", -1); // -1: unknown, 0: false, 1: true
FUZZ_SET_ATTR_INT(path, "approx_len", (int)base.size());

